CREATE TABLE "public"."sector" (
  "id"          bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"  timestamp with time zone DEFAULT now(),
  "description" text,
  "name"        text                     NOT NULL,
  CONSTRAINT "sector_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."sector"
  ENABLE ROW LEVEL SECURITY;

CREATE POLICY "Enable read access for all users" ON "public"."sector"
  FOR SELECT
  TO "anon", "authenticated"
  USING (true);

REVOKE ALL ON SEQUENCE "public"."sector_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sector_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."sector_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sector_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."sector_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sector_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."sector_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."sector_id_seq" TO "service_role";

GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."sector" TO "anon", "authenticated";

GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."sector" TO "service_role";

COMMENT ON TABLE "public"."sector" IS 'Setor de Highlines';

REVOKE ALL ON TABLE "public"."sector" FROM "postgres";

GRANT DELETE, INSERT, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."sector" TO "postgres";
